// ✅ Create a regex with groups
Pattern pattern = Pattern.compile("(\\d{4})-(\\d{2})-(\\d{2})"); // yyyy-mm-dd format
Matcher matcher = pattern.matcher("Date: 2025-10-12");

// ✅ Check and extract groups
if (matcher.find()) {
